import{_ as t,o as n,c as a,a0 as o}from"./chunks/framework.L_oL6aia.js";const p=JSON.parse('{"title":"🚀 Built an Enterprise AI Agent at Microsoft HQ OpenHack! 🍕🤖","description":"","frontmatter":{},"headers":[],"relativePath":"linkedin-post.md","filePath":"linkedin-post.md"}'),r={name:"linkedin-post.md"};function s(i,e,l,c,d,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="🚀-built-an-enterprise-ai-agent-at-microsoft-hq-openhack-🍕🤖" tabindex="-1">🚀 Built an Enterprise AI Agent at Microsoft HQ OpenHack! 🍕🤖 <a class="header-anchor" href="#🚀-built-an-enterprise-ai-agent-at-microsoft-hq-openhack-🍕🤖" aria-label="Permalink to &quot;🚀 Built an Enterprise AI Agent at Microsoft HQ OpenHack! 🍕🤖&quot;">​</a></h1><p>I recently attended the <strong>Microsoft AI Foundry Workshop OpenHack</strong> and built <strong>Contoso PizzaBot</strong>—a fully functional, domain-specific AI assistant that leverages state-of-the-art agentic architectures!</p><p>Here is a summary of the tech stack and architecture I implemented:</p><h3 id="🛠️-the-tech-stack-architecture" tabindex="-1">🛠️ The Tech Stack &amp; Architecture: <a class="header-anchor" href="#🛠️-the-tech-stack-architecture" aria-label="Permalink to &quot;🛠️ The Tech Stack &amp; Architecture:&quot;">​</a></h3><ul><li><strong>Orchestration</strong>: Built using the new <strong>Azure AI Foundry Client SDK</strong> and stateful <strong>Agent Service</strong> runs.</li><li><strong>Base Model</strong>: Powered by <strong>GPT-4o</strong> for advanced natural language understanding and reasoning.</li><li><strong>Retrieval-Augmented Generation (RAG)</strong>: Grounded the agent with localized store branch details (Boston, Amsterdam, San Francisco) by dynamically querying search indexes in an <strong>Azure AI Search Vector Store</strong>.</li><li><strong>Deterministic Action Tools</strong>: Configured strict local Python <strong>Function Tools</strong> to handle precise quantity calculations (estimating order sizes based on group sizes) without relying on LLM math.</li><li><strong>Model Context Protocol (MCP)</strong>: Integrated the agent with live ordering systems over <strong>Server-Sent Events (SSE)</strong> Container Apps using the new open-standard MCP. The agent dynamically discovers tools to pull menus, toppings, and manage order placements!</li></ul><hr><h3 id="💡-key-skills-takeaways" tabindex="-1">💡 Key Skills &amp; Takeaways: <a class="header-anchor" href="#💡-key-skills-takeaways" aria-label="Permalink to &quot;💡 Key Skills &amp; Takeaways:&quot;">​</a></h3><ol><li><strong>Agentic Personas &amp; Safety</strong>: Mastered designing detailed system prompts to enforce strict domain guardrails, handle personality quirks (like playful pineapple-on-pizza snark 🍍), and implement Human-in-the-Loop order confirmations.</li><li><strong>Unified Abstractions (MCP)</strong>: Experienced firsthand how MCP solves the API integration problem. Instead of writing custom endpoints for every database or dashboard, you hook into an MCP server and tools are dynamically resolved by the agent.</li><li><strong>State Management</strong>: Orchestrated stateful conversational threads, runs, and local tool call execution interception using the Azure AI SDK.</li></ol><p><em>Special thanks to the Microsoft team for hosting such a high-impact, hands-on hackathon!</em></p><p>👉 Check out the source code in the repository: <code>agent.py</code></p><p>#AzureAIFoundry #Azure #OpenAI #AIAgents #ModelContextProtocol #RAG #MachineLearning #Python #CloudComputing #MicrosoftOpenHack</p>',11)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
